/**
 * dsh-notifier — 审批/完成/错误事件通知（宿主端）。
 *
 * 本文件只做装配：apply + 事件订阅 + 生命周期清理。职责划分：
 * - config.ts      配置契约/默认值/validateSettings/sanitize*Settings/迁移源路径
 * - quiet-hours.ts 免打扰判定（parseHHMM / isInQuietHours）
 * - message.ts     通知文案单表/脱敏/格式化/agent 事件读取（纯函数）
 * - history.ts     通知历史 jsonl 存储（滚动/按天清理/原子写）
 * - settings.ts    官方 settings 命名空间接线（installNotifierSettings，issue #76）
 * - migrate.ts     存量自建 json 一次性迁移（E1-E7/R1）
 * - server.ts      SSE 枢纽 + 系统通知通道 + HTTP 路由
 *
 * 配置（issue #76）：官方 settings 命名空间为唯一事实源（settings.yaml 单一
 * 存储）；组合层通知配置作为命名空间 base 层；旧 `~/.dsh/dsh-notifier.json`
 * 启动时一次性迁移（改名 .migrated.bak / 损坏 .corrupted.bak）。enabled 为
 * 组合层开关：禁用态仍注册路由+命名空间+迁移（H2/H3），notify() 入口判定。
 * 读取面经描述器（describe redactSecrets）取 user/revision，写入面经
 * service.update(ns, patch, expectedRevision) 乐观并发。
 *
 * 事件源（均经源码核验）：
 * - 审批请求：approval/request waterfall（ApprovalService.request 派发；
 *   真实触发方为沙箱提权 / 动态插件激活等。tools/pre-execute 的 gate ask
 *   在当前 DSH 部署中无产生者，不可用）。在 next() 之前通知（next 阻塞到
 *   用户审批结束），不短路
 * - 任务完成：agent/status（scoped emit，{agent, status}，idle | running）
 *   running → idle 跃迁，per-agent 状态机，多会话互不误报；子代理
 *   （origin === 'subagent'，或 fork 型委派且运行时归属成立——见 message.ts
 *   isSubagentOf 双信号注释）走独立开关/事件类型 subagent-done；
 *   用户暂停/中断（turn/end reason aborted）固定静默。
 *   完成判定为单源 push + 快照兜底（issue #290 阶段二）：idle 判定以
 *   session/event 推送流记忆（eventStreamEnds，post-commit 同步派发、恒定
 *   新鲜）为主证据源；快照回读（lastTurnEndOf）仅在 push 缺失（插件中途
 *   挂载 / 重载窗口内已派发但新 fiber 未记忆）时作兜底——快照一次性读滞后
 *   不再被 lastEndedTurn 固化为永久静默；同一 turn 两源汇合于同一判定点，
 *   天然只通知一次。abort-early（本轮无新 closure）陈旧快照经 running 基线
 *   守卫拦截，不误报完成。跳过路径输出可观测 warn（标识证据来源）。
 * - 任务错误：agent/error（{agent, turn, step, error}），60 秒滚动窗口合并
 * - 轮结束：agent/turn-stopping（serial，{agent, turn}，仅宿主通知，不跑模型）
 * - 会话销毁：agent/disposed（清理 per-agent 状态）
 *
 * 通道：
 * - 系统通知：Windows PowerShell WinRT toast（lib/toast.ps1，零依赖）；
 *   Linux/macOS 用 notify-send（存在才调用）；均失败则仅记录日志
 * - 浏览器通知：SSE（text/event-stream，mcp-manager 同款模式）推帧，
 *   客户端 Notification API 展示（页面隐藏时）
 *
 * 配置路径（issue #76 后）：官方 settings 命名空间（设置 → 插件 → dsh-notifier
 * 卡片 PUT /config 写，落盘官方 settings.yaml）；旧 ~/.dsh/dsh-notifier.json 仅
 * 作为存量迁移源，迁移后改名归档，不再读写。
 * 安全：通知文本只含工具名/会话标识/申请理由等元信息，不含工具参数（防敏感信息外泄）。
 */
// 官方类型层（issue #16，锁 0.1.1-rc.2；仅 import type，编译期擦除，
// 禁止运行时值导入——contract-check 有门禁）。session/title 事件键由
// dsh-session-title 经 declare module 注入 SessionEventMap，必须引入其类型面。
import type { Context } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type {} from "@deepseek-ai/dsh-session/types";
import type {} from "@deepseek-ai/dsh-session-title";
import type {} from "@deepseek-ai/dsh-user-approval";
import { errorMessage } from "../../../shared/host-utils.js";
import { CONFIG_KEYS, DEFAULT_CONFIG, configFile, historyFile, statusFile, normalizeConfig, sanitizeSettings, toastScriptPath } from "./config.ts";
import type { NotifierApplyConfig, NotifyConfig } from "./config.ts";
import { isInQuietHours } from "./quiet-hours.ts";
import { HISTORY_LIMIT, createHistoryStore } from "./history.ts";
import { createDoneBatcher } from "./aggregate.ts";
import type { DoneBatcher } from "./aggregate.ts";
import { sanitizeErrorText, sessionTitleOf, isSubagentOf, lastTurnEndOf } from "./message.ts";
import type { NotifyDetail } from "./message.ts";
import { SETTINGS_NS, installNotifierSettings } from "./settings.ts";
import type { OwnerScopeLike, SettingsServiceLike } from "./settings.ts";
import { migrateLegacyConfig } from "./migrate.ts";
import { ROUTES, buildRoutes, createSseHub, createSystemNotifier } from "./server.ts";
import { createNotifierService } from "./service.ts";
import type { NotifierServiceInternal, NotifyChannel, NotifySentEvent } from "./service.ts";
import { createStatusStore } from "./status.ts";
import { createBarkChannel, createBarkGate } from "./channel-bark.ts";
import { createWebhookChannel } from "./channel-webhook.ts";

/** 稳定的 cordis 插件名。 */
export const name = "notifier";

/** 需要的服务：webServer（路由）。 */
export const inject = ["webServer"];

// ---------------------------------------------------------------- 导出面
// 公共符号定义在各职责模块，此处统一 re-export——包导出面与拆分前完全一致。

export { QUIET_ALLOW_KINDS, isInQuietHours, parseHHMM } from "./quiet-hours.ts";
export type { QuietHoursConfig } from "./quiet-hours.ts";
export { CONFIG_KEYS, DEFAULT_CONFIG, ASSEMBLY_SETTING_KEYS, configFile, historyFile, statusFile, normalizeConfig, sanitizeSettings, sanitizePatchSettings, validateSettings, toastScriptPath, normalizeBarkBaseUrl, normalizeBarkLevels, redactConfigView, unmaskChannels, SECRET_MASK, BARK_ID_PATTERN, BARK_RESERVED_KEYS } from "./config.ts";
export type { NotifierApplyConfig, NotifyConfig, SettingInvalid, BarkChannelConfig, BarkLevel } from "./config.ts";
export { HISTORY_LIMIT } from "./history.ts";
export { SETTINGS_NS, installNotifierSettings } from "./settings.ts";
export { migrateLegacyConfig, MIGRATED_BAK_SUFFIX, CORRUPTED_BAK_SUFFIX } from "./migrate.ts";
export { createStatusStore } from "./status.ts";
export type { StatusStore, ChannelStatusEntry } from "./status.ts";
export { createBarkChannel, createBarkGate, SEVERITY_LEVEL, BARK_TIMEOUT_MS, BARK_RETRIES, BARK_MAX_INFLIGHT } from "./channel-bark.ts";
// #508 M2：webhook 频道公开面（渲染器/映射表导出供消费方与测试直测）
export { createWebhookChannel, renderWebhookBody, priorityFor, SEVERITY_NTFY_PRIORITY, SEVERITY_GOTIFY_PRIORITY, WEBHOOK_DEFAULT_TIMEOUT_SEC, WEBHOOK_MIN_TIMEOUT_SEC, WEBHOOK_MAX_TIMEOUT_SEC } from "./channel-webhook.ts";
export type { MigrationOutcome } from "./migrate.ts";
export {
  buildSystemCommand,
  formatDuration,
  isSubagentOf,
  lastTurnEndOf,
  prettyToolName,
  sanitizeErrorText,
  sessionTitleOf,
} from "./message.ts";
export type { NotifyDetail } from "./message.ts";
export { ROUTES, applyConfigPatch } from "./server.ts";
export type { PatchResult, RouteDeps } from "./server.ts";
export {
  BUILTIN_CHANNELS,
  KIND_SEVERITY,
  createNotifierService,
  getNotifierService,
} from "./service.ts";
export type {
  ChannelCapabilities,
  KindRegistration,
  NotifyChannel,
  NotifyRequest,
  NotifyResult,
  NotifierService,
  NotifierServiceDeps,
  NotifierServiceInternal,
  NotifySeverity,
} from "./service.ts";

// 辅助函数统一来自仓库共享层（loopback 围栏 / writeJson / readBody / errorMessage）。
export { isLoopbackRequest } from "../../../shared/loopback.js";
export { writeJson, readBody, errorMessage } from "../../../shared/host-utils.js";

/**
 * 挂载 dsh-notifier。
 * @param ctx 宿主插件上下文。
 * @param config 配置（enabled / configFile 迁移源 / toastScript 覆盖）。
 */
export function apply(ctx: Context, config: NotifierApplyConfig = {}): void {
  // 组合层通知配置（settings 命名空间的 base 层；enabled 是组合层开关，不进
  // user 层）。注意：应用配置现在只读 settings 命名空间解析值 + 本 entry。
  const entry = (sanitizeSettings(config) ?? {}) as Record<string, unknown>;
  const storeFile = typeof config.configFile === "string" ? config.configFile : configFile();
  const toastScript = typeof config.toastScript === "string" ? config.toastScript : toastScriptPath();
  const historyPath = typeof config.historyFile === "string" ? config.historyFile : historyFile();

  /**
   * 当前配置（运行时镜像，与 settings 命名空间解析值保持同步）。
   * settings attach 后由 setSource 指向 scope.get()，变更经 onChange 刷新；
   * 服务缺失时回落组合层 entry——setSource/onChange 均经 normalizeConfig 收口，
   * 回落形态与初始一致（同键同值、默认值兜底，与 attach 态同源）。
   */
  let current: NotifyConfig = normalizeConfig(entry);
  /** settings 读取来源 thunk（attach 后为 scope.get()）。 */
  let source: () => NotifyConfig = () => current;
  /** settings 服务 attach 状态（writable / readUser 依据）。 */
  let attachedService: SettingsServiceLike | undefined;
  /** attach 后的 owner scope（迁移写入面）。 */
  let attachedScope: OwnerScopeLike | undefined;
  /** 读取 settings user 层（描述器 redactSecrets 后取 user/revision）。 */
  function readUser(): { user: Record<string, unknown>; revision?: number } {
    if (!attachedService) return { user: {}, revision: undefined };
    try {
      const descriptor = attachedService.describe({ redactSecrets: true }).find((d) => d.ns === SETTINGS_NS);
      return {
        user: (descriptor?.user && typeof descriptor.user === "object" ? descriptor.user : {}) as Record<string, unknown>,
        revision: descriptor?.revision,
      };
    } catch {
      return { user: {}, revision: undefined };
    }
  }

  // ------------------------------------------------------------ 组装各职责模块

  const sse = createSseHub({ getMaxConnections: () => current.maxConnections });
  const system = createSystemNotifier({
    getSoundEnabled: () => current.notifySound,
    toastScript,
    warn: (message) => ctx.logger.warn(message),
  });
  const historyStore = createHistoryStore({
    file: historyPath,
    maxAgeDays: () => current.historyMaxAgeDays,
    warn: (message) => ctx.logger.warn(message),
  });
  const statusPath = typeof config.statusFile === "string" ? config.statusFile : statusFile();
  const statusStore = createStatusStore({
    file: statusPath,
    warn: (message) => ctx.logger.warn(message),
  });

  // ------------------------------------------------------------ 出站频道（M2：bark）

  /** Bark 实例级在途限流门（按 cfg.id 键控；同 id 跨配置变更延续门状态）。 */
  const barkGates = new Map<string, ReturnType<typeof createBarkGate>>();
  function gateFor(id: string) {
    let gate = barkGates.get(id);
    if (!gate) {
      gate = createBarkGate();
      barkGates.set(id, gate);
    }
    return gate;
  }

  /**
   * 配置驱动的出站频道（enabled 的实例，#508 M2：bark + webhook 按类型分派）：
   * 每次 dispatch 现取现建——配置热更新（PUT /config）即时生效；在途投递持有
   * 旧实例自然结束（终稿 §10）。channel 实例是轻量闭包，重建无负担；限流门按
   * id 延续（评审 P1）。频道路由 id = `type:id`（与 service resolveRoutes /
   * 客户端 channelIdFor 同语义，复核 4② 单点）。
   */
  function outboundChannels(): Array<{ id: string; channel: NotifyChannel }> {
    const out: Array<{ id: string; channel: NotifyChannel }> = [];
    for (const c of current.channels ?? []) {
      if (!c.enabled) continue;
      if (c.type === "bark") out.push({ id: `bark:${c.id}`, channel: createBarkChannel(c, gateFor(c.id)) });
      else if (c.type === "webhook") out.push({ id: `webhook:${c.id}`, channel: createWebhookChannel(c) });
    }
    return out;
  }

  /** 投递终态事件（'wingsky-notify/sent'）：宿主无事件总线时静默跳过（探测面）。 */
  function emitSent(payload: NotifySentEvent): void {
    try {
      (ctx as unknown as { emit?: (name: string, ...args: unknown[]) => void }).emit?.("wingsky-notify/sent", payload);
    } catch {
      // 事件派发失败不影响投递语义（终态仍可见于 status 文件与历史）
    }
  }

  /** settings user 层增量写入（PUT /config 与 kind 确认共用的写通道）。 */
  function updateConfig(patch: object, expectedRevision?: number): Promise<void> {
    const service = attachedService;
    if (!service) {
      // 服务缺失的 rejection 挂 code（#405 PR3 复核）：与 service.update 抛出的
      // SETTINGS_CONFLICT 同面，供调用方（PUT 503 分支 / kinds handler 兜底）按
      // code 分流，避免依赖底层错误文案判断。
      const err = new Error("settings service unavailable") as Error & { code?: string };
      err.code = "SETTINGS_UNAVAILABLE";
      return Promise.reject(err);
    }
    // 乐观并发（F4）必须经 service.update(ns, ...)（SettingsProvider 公开
    // 方法，write 内做 revision 校验）——scope.update 会丢弃该参数。
    return service.update(SETTINGS_NS, patch, expectedRevision);
  }

  /**
   * 动态 kind 确认 → 配置 allowKinds（M2：确认态持久化）。#405 PR3：read-modify-
   * write CAS 循环（评审 P0-1/P2-1 落实）——
   * - 允许集数据源 = user 层原始节 allowKinds，user 层未接管（无该键）时回退解析值
   *   （组合层 base/默认值）——若只读 user 层，base 配置的豁免项会在首次确认时被
   *   空集整键覆盖清空（合并 patch 顶层键浅合并语义）；
   * - 带 expectedRevision（readUser().revision）提交；SETTINGS_CONFLICT（另一端
   *   并发写入推进了 revision）→ 重拉重算重试 ≤2 次；耗尽/其他错误上抛给调用方；
   * - 请求方向零契约变更（POST /kinds 不新增字段）：客户端传 revision 是与服务端
   *   CAS 循环重复的防御（allowKinds 唯一写者即本函数），已砍。所有调用方（HTTP
   *   路由 + service 内部 fire-and-forget 链）统一收口进同一 CAS。
   */
  async function confirmKindToConfig(kind: string, confirmed: boolean): Promise<void> {
    const MAX_CONFLICT_RETRIES = 2;
    for (let attempt = 0; ; attempt += 1) {
      const { user, revision } = readUser();
      const resolved = source();
      const baseAllowed = Array.isArray(user.allowKinds)
        ? user.allowKinds
        : Array.isArray(resolved.allowKinds)
          ? resolved.allowKinds
          : [];
      const allowed = new Set<string>(baseAllowed);
      if (confirmed) allowed.add(kind);
      else allowed.delete(kind);
      try {
        await updateConfig({ allowKinds: [...allowed] }, revision);
      } catch (err) {
        const code = (err as { code?: unknown })?.code;
        if (code === "SETTINGS_CONFLICT" && attempt < MAX_CONFLICT_RETRIES) continue;
        throw err;
      }
      // 提交后主动同步镜像（watch 回调异步「提交后串行」；随后幂等刷新一次）。
      current = source();
      return;
    }
  }

  // ------------------------------------------------------------ 通知中心 service（M1）

  /**
   * 通知中心核心服务：'wingsky.notifier'（M1，issue #366）。
   * - 内置事件源经 service.sendKind 走完整文案管线（等价搬移前 notify 语义）；
   * - 外部调用方（hub 插件）经 ctx['wingsky.notifier'].send 发送（缺省广播）；
   * - 动态 kind 注册 → 待确认 → 确认后放行（suppressed 落史复用免打扰路径）。
   * 依赖注入与旧装配层完全同源（sse/system/history/current/enabled），
   * 无新状态面；卸载随 fiber disposer 统一清理（service 本身无定时器）。
   */
  const notifierService: NotifierServiceInternal = createNotifierService({
    current: () => current,
    enabled: () => config.enabled !== false,
    sse,
    system,
    history: historyStore,
    logger: ctx.logger,
    outboundChannels,
    recordStatus: (channelId, status, error) => statusStore.record(channelId, status, error),
    emitSent,
    setConfirm: (kind, confirmed) => {
      confirmKindToConfig(kind, confirmed).catch((err) => {
        ctx.logger.warn(`dsh-notifier: kind 确认写入失败 — ${errorMessage(err)}`);
      });
    },
  });
  // 暴露服务（官方 storageDomain 模式，mcp-manager 同款）：fake ctx 无 provide
  // 时静默降级（单测 mock 兼容）。重复 provide 同名服务 cordis 会抛错——本插件
  // 单实例无竞态；若出现，属装配错误应显式失败。
  if (typeof (ctx as unknown as { provide?: unknown }).provide === "function") {
    (ctx as unknown as { provide: (name: string, svc: unknown) => void }).provide("wingsky.notifier", notifierService);
  }

  /** 通知历史追加（fire-and-forget 落盘，见 history.ts）。 */
  function appendHistory(entry: { ts: number; kind: string; title: string; message: string; suppressed?: string }) {
    historyStore.append(entry);
  }

  // ------------------------------------------------------------ 通知主入口

  /**
   * 通知入口（M1：委托通知中心 service，行为与搬移前完全一致）。
   * - enabled 总开关（H3）、免打扰检查（suppressed 落史）、fail-soft 逐频道
   *   分发、历史落盘全部收敛到 service.sendKind（单一管线，评审 #1）；
   * - 返回 boolean 语义保持：results 中存在任一 ok 频道 = 真正发出。
   * @param kind ask / done / error / turn-end 等内置 kind。
   * @param detail {tool?, taskTitle?, reason?, durationMs?, turn?, step?, message?, mergedCount?}（不含工具参数）。
   */
  function notify(kind: string, detail: NotifyDetail = {}): boolean {
    const results = notifierService.sendKind(kind, detail);
    return results.some((r) => r.status === "ok");
  }

  // ------------------------------------------------------------ 事件监听

  const disposers: Array<() => void> = [];

  /**
   * 任务完成状态机（per-agent）：见到某会话 running 记 pendingDone，下次该会话
   * idle 时判定是否通知（带耗时）。多会话/子代理各自独立跟踪，互不误报。
   * 子代理（isSubagentOf 双信号：origin === 'subagent' 或 fork 型委派运行时
   * 归属成立）走独立开关 notifySubagentDone 与独立事件类型 subagent-done；
   * 用户暂停/中断（turn/end reason aborted）固定静默。
   */
  const agentStates = new Map<string, { runningSeen: boolean; startedAt: number; lastEndedTurn?: number; runningBaseline?: { turn: number; kind: string } }>(); // agentId -> { runningSeen, startedAt, lastEndedTurn, runningBaseline }

  /**
   * 审批请求：approval/request waterfall（源码核验：真实审批由 dsh-sandbox
   * 提权 / 动态插件激活等调用 ApprovalService.request 触发；tools/pre-execute
   * 的 gate ask 在当前 DSH 部署中无产生者，故不挂那里）。在 await next()
   * 之前通知——next() 会阻塞到用户审批结束，这正是"等待审批"提醒的时机；
   * 不短路，返回 next() 结果。
   */
  /** 审批超时二次提醒：per-request 定时器表；next() settle（用户已决定）即清除。 */
  const askRemindTimers = new Map<string, NodeJS.Timeout>();

  disposers.push(
    ctx.on("approval/request", async (req, next) => {
      if (!current.notifyAsk) return next();
      const askDetail = () => ({
        tool: req?.toolName as string | undefined,
        taskTitle: sessionTitleOf(req?.agent),
        // 审批理由最常内嵌命令回显与凭据片段，进通知前必须脱敏（120 字符截断）
        reason: req?.reason ? sanitizeErrorText(req.reason, 120) : undefined,
      });
      try {
        notify("ask", askDetail());
      } catch (error) {
        ctx.logger.warn(`dsh-notifier: approval/request 通知失败: ${errorMessage(error)}`);
      }
      // 审批超时二次提醒（askRemindMin 分钟未响应再弹一条，正文带已等待时长）。
      // DSH 无 "approval/decided" 的 cordis 事件可监听——审批结束的唯二信号是
      // next() Promise 的决议/拒绝（对抗评审共识③），故定时器绑定 next() settle。
      const askKey = req?.agent?.id ?? String(req?.toolName ?? "?");
      if (current.askRemindMin > 0) {
        const timer = setTimeout(() => {
          if (askRemindTimers.get(askKey) === timer) {
            askRemindTimers.delete(askKey);
            try {
              notify("ask", { ...askDetail(), remindMinutes: current.askRemindMin });
            } catch (error) {
              ctx.logger.warn(`dsh-notifier: 审批超时提醒失败: ${errorMessage(error)}`);
            }
          }
        }, current.askRemindMin * 60000);
        timer.unref(); // 不阻止进程退出（服务有主循环；测试环境不挂死）
        askRemindTimers.set(askKey, timer);
      }
      try {
        return await next();
      } finally {
        const t = askRemindTimers.get(askKey);
        if (t !== undefined) {
          clearTimeout(t);
          askRemindTimers.delete(askKey);
        }
      }
    }, { global: true })
  );

  /**
   * 用户提问通知：dsh-user-questions 的 service 不发出任何 cordis 事件
   * （ask() 直连 UI provider），故包装 service 的 ask 方法补发通知。
   * 热重载安全：svc.ask 上若残留上一 fiber 的包装（__dshNotifierWrapped），
   * 先解包取原始实现再包装——保证包装始终指向当前 fiber 的 SSE 连接，
   * 避免旧包装广播到已失效连接导致「历史有记录但收不到提醒」。
   */
  /** userQuestions service 的 ask 方法（含热重载解包字段）。 */
  interface AskFunction {
    (request: unknown): Promise<unknown>;
    __dshNotifierWrapped?: boolean;
    __dshNotifierOriginal?: AskFunction;
  }

  function hookUserQuestions() {
    let svc: { ask?: unknown } | undefined;
    try {
      svc = typeof ctx.get === "function" ? (ctx.get("userQuestions", false) as { ask?: unknown } | undefined) : undefined;
    } catch {
      svc = undefined;
    }
    if (!svc || typeof svc.ask !== "function") return;
    // 解包：跳过上一 fiber 的残留包装，取原始 ask
    let original: AskFunction = svc.ask as AskFunction;
    if (typeof original.__dshNotifierWrapped === "boolean" && typeof original.__dshNotifierOriginal === "function") {
      original = original.__dshNotifierOriginal;
    }
    // ⚠️ ask 是依赖 this 的类方法：必须 bind 到 service 实例，
    // 否则调用时 this 为 undefined（"Cannot read properties of undefined"）。
    // __dshNotifierOriginal 存已 bind 版本，热重载解包后直接可调用。
    const callOriginal: AskFunction = original.bind(svc);
    const wrapped = (async (request: unknown) => {
      try {
        if (current.notifyQuestion) {
          const first = Array.isArray(request && (request as { questions?: unknown[] }).questions) ? (request as { questions?: unknown[] }).questions![0] : undefined;
          notify("question", {
            tool: "ask_user_question",
            taskTitle: sessionTitleOf((request as { agent?: Agent } | null | undefined)?.agent),
            // 提问文本同样可能内嵌上下文片段，进通知前脱敏（120 字符截断）
            question: first && (first as { question?: unknown }).question ? sanitizeErrorText((first as { question?: unknown }).question, 120) : undefined,
          });
        }
      } catch (error) {
        ctx.logger.warn(`dsh-notifier: 提问通知失败: ${errorMessage(error)}`);
      }
      return callOriginal(request);
    }) as AskFunction;
    wrapped.__dshNotifierWrapped = true;
    wrapped.__dshNotifierOriginal = callOriginal;
    svc.ask = wrapped;
  }

  // 启动时若 service 已注册则立即包装；未注册则等 internal/service 事件兜底。
  hookUserQuestions();
  disposers.push(
    ctx.on("internal/service", (name) => {
      if (name === "userQuestions") hookUserQuestions();
    }, { global: true })
  );

  /**
   * 完成通知风暴聚合（done / subagent-done）：M0 纯搬移为独立模块
   * （src/aggregate.ts createDoneBatcher），语义与搬移前完全一致——首条
   * 「完成」立即原样通知 + 起 doneMergeWindowMs 窗口（0=关闭聚合），窗口内
   * 后续完成只累积标题与计数，窗口到点**补发一条聚合通知**。窗口定时器
   * unref，卸载时由全局 disposer 调 dispose() 清空。
   */
  const doneBatcher: DoneBatcher = createDoneBatcher({
    getWindowMs: () => current.doneMergeWindowMs,
    notify,
  });

  /**
   * 完成判定辅源记忆（issue #272）：session/event 推送流记录的 per-session
   * 最新 turn/end。主源在 idle 时从 agent.session.snapshotEvents() 快照回读 turn/end，
   * 该读是一次性快照——任何一次读滞后都会被下方 lastEndedTurn 的无条件推进
   * 固化为「后续 turn 全部已处理」的永久静默（#272 报告场景的根因）。本推送
   * 源 post-commit 逐条派发（官方 SessionEventMap 声明面），不依赖快照回读，
   * 作为互补证据根治单点依赖。仅记最新一条：完成判定只关心「比已通知 turn
   * 更新的闭合」，历史无用；agent/disposed 时随状态机一并清理。
   */
  const eventStreamEnds = new Map<string, { turn: number; kind: string }>(); // sessionId -> 最新推送 turn/end

  disposers.push(
    ctx.on("session/event", (session, event) => {
      try {
        if (event?.type !== "turn/end") return;
        const reason = event.data?.reason;
        if (reason === undefined || reason === null || typeof reason !== "object") return;
        // 运行时防御同 lastTurnEndOf（payload 跨宿主边界，不受信）
        const sessionId = session?.id !== undefined ? String(session.id) : undefined;
        if (sessionId === undefined) return;
        const turn = typeof event.data?.turn === "number" ? event.data.turn : NaN;
        if (!Number.isFinite(turn)) return; // 非有限 turn 的证据不可用：直接 skip 不落记忆，
        // 否则 {turn:NaN} 会在合并处凭 ended===undefined 短路成 best、经首轮
        // rememberedTurn===undefined 放行误报后把 lastEndedTurn 推进为 NaN，
        // 此后真实完成因 x > NaN 恒 false 被永久吞掉（#284 复核闸 P1）。
        eventStreamEnds.set(sessionId, {
          turn,
          kind: String((reason as { kind?: unknown }).kind ?? ""),
        });
      } catch (error) {
        ctx.logger.warn(`dsh-notifier: session/event 处理失败: ${errorMessage(error)}`);
      }
    }, { global: true })
  );

  /**
   * 任务完成：agent/status running → idle 跃迁（按 agent 分组）。
   * 分支不再被 notifyTaskDone 门控（否则 notifyTaskDone=false +
   * notifySubagentDone=true 时子代理完成被拦下）：进入即先取耗时并
   * 无条件重置状态，再做中断抑制与主/子分流。
   */
  disposers.push(
    ctx.on("agent/status", ({ agent, status }) => {
      try {
        const agentId = agent?.id ?? "?";
        let state = agentStates.get(agentId);
        if (state === undefined) {
          state = { runningSeen: false, startedAt: 0 };
          agentStates.set(agentId, state);
        }
        if (status === "idle" && state.runningSeen) {
          const durationMs = state.startedAt > 0 ? Date.now() - state.startedAt : 0;
          // 无条件重置（顺带修复既有 bug：notifyTaskDone=false 时 runningSeen
          // 不重置，之后重开开关会误报很久以前的「完成」）。
          state.runningSeen = false;
          state.startedAt = 0;
          // 中断抑制（S1）：本轮 idle 必须闭合了新的 turn/end 才判定结束。
          // 「abort 早于本轮 turn/start 落盘」时本轮无 turn/end（loop turn()
          // 首行 throwIfAborted 在 try 外），读到的 turn/end 是上一次运行的
          // ——无新 closure 宁可静默，不误报完成。
          //
          // 证据面收敛——单源 push + 快照兜底（issue #290 阶段二）：
          // 完成判定证据主源 = session/event 推送流（eventStreamEnds，
          // post-commit 同步派发、恒定新鲜）：eventStreamEnds 有该 session
          // 记录时直接采信 push、不读快照。快照回读（lastTurnEndOf）仅在
          // push 缺失（插件于 agent 运行中途挂载 / 重载窗口内已派发但新
          // fiber 未记忆）时作兜底——不再「按 turn 取新」双源互补。
          //
          // abort-early 陈旧快照冻结（C-1）：兜底快照必须较 running 基线
          // 推进才视为「本轮新 closure」——abort 早于本轮 turn/start 落盘
          // 时本轮无新 turn/end，快照读到的仍是上一次运行的 completed；若
          // 快照 turn ≤ running 基线（本轮无推进），把陈旧快照冻结、不作
          // 本轮证据（宁静静默，不误报完成）。状态机记忆为空（重载后首次
          // idle）时同样成立：记忆重置不把旧证据当新轮完成（D-2）。
          const streamedRaw = eventStreamEnds.get(agentId);
          // 合并处对称守卫（#284 复核闸 P1 纵深）：仅接受 turn 有限的证据——
          // 入口（lastTurnEndOf / session/event 处理器）已各自 skip 非有限
          // turn，此处兜底保证任何畸形证据既不能成 best、也不能推进记忆。
          const pushed = streamedRaw !== undefined && Number.isFinite(streamedRaw.turn) ? streamedRaw : undefined;
          // 快照兜底仅在 push 缺失时读取（单源 push 为主证据，不读快照）。
          const snapshot = pushed === undefined ? lastTurnEndOf(agent) : undefined;
          const baselineTurn = state.runningBaseline?.turn;
          const stale =
            pushed === undefined &&
            snapshot !== undefined &&
            baselineTurn !== undefined &&
            snapshot.turn <= baselineTurn;
          const best = pushed ?? (stale ? undefined : snapshot);
          const evidenceSource = pushed !== undefined ? "push" : snapshot !== undefined ? (stale ? "快照冻结" : "快照兜底") : "无";
          const rememberedTurn = state.lastEndedTurn;
          const hasNewEnd = best !== undefined && (rememberedTurn === undefined || best.turn > rememberedTurn);
          // 非正常结束不判「完成」：本轮 turn/end 无新 closure（hasNewEnd）
          // 或 kind 属于 aborted/interrupted/error/blocked 时静默——失败由
          // agent/error 单独负责「任务出错」通知，被阻塞由对应事件负责，
          // 避免同一轮既报异常又误报「任务完成」。
          // - aborted：用户停止生成（agent.cancel {kind:"user"}）与中断
          //   interrupt_agent 均落此值；interrupted 为未来兼容保留。
          // - error：任务运行失败（dsh-agent-loop turn 的 catch 分支写入）。
          // - blocked：本轮被阻塞（preStep reject，如等待用户问题）提前结束。
          // 完成判定用白名单：仅 kind === "completed" 才通知「任务完成」。
          // max-tokens（输出被截断）与一切未知 kind 一律静默——避免把非正常
          // 结束误报为完成（与 DSH accountsForClaim 对未知 kind 保守不成功的
          // 语义对齐；失败由 agent/error 单独负责「任务出错」）。
          if (!hasNewEnd || best === undefined || best.kind !== "completed") {
            // P0 warn 兜底（issue #272）：跳过路径必须可观测——#272 的报告
            // 场景正是该分支全程零日志，静默固化无从排查。warn 只进服务端
            // 日志，不打扰用户；aborted 等设计内静默同样留痕（kind 字段区分）。
            ctx.logger.warn(
              `dsh-notifier: 完成判定跳过（不发 done）agent=${agentId} kind=${best?.kind ?? "none"} ` +
                `证据源=${evidenceSource} 快照turn=${snapshot !== undefined ? String(snapshot.turn) : "-"} ` +
                `推送turn=${pushed !== undefined ? String(pushed.turn) : "-"} ` +
                `记忆turn=${rememberedTurn ?? "-"}`,
            );
            // B-3：非 completed 闭包照常消费——aborted/error/blocked/
            // max-tokens/未知 kind 照旧跳过通知（不误报完成），但
            // lastEndedTurn 照常推进（同 turn 再现 idle 不重复处理）。
            if (best !== undefined) state.lastEndedTurn = best.turn;
            return;
          }
          const taskTitle = sessionTitleOf(agent);
          // 子代理判定（issue #49 双信号）：origin 命中即 spawn 型；未命中查
          // 运行时归属（fork 型委派 worker）；归属不成立/agents 服务缺位一律
          // 保守走主任务分支——用户 fork 主线不被静默。三类 header 形态与
          // 冷 resume 保守边界见 isSubagentOf 注释。
          // 根因 A 安全化（issue #290）：agents 服务未注入（inject 仅
          // ["webServer"]）时 cordis 严格属性访问会抛 cannot get property
          // "agents" without inject——必须经 ctx.get(name, false) 安全读取
          // （L258 userQuestions 同款先例），缺位返回 undefined → 走主任务分支，
          // 不再触发 THROW truthy 误判。显式防御 typeof ctx.get 兼容 fake ctx。
          const agents = typeof ctx.get === "function" ? ctx.get("agents", false) : undefined;
          if (isSubagentOf(agent, agents)) {
            if (current.notifySubagentDone) doneBatcher.enqueue("subagent-done", taskTitle, durationMs);
          } else if (current.notifyTaskDone) {
            doneBatcher.enqueue("done", taskTitle, durationMs);
          }
          // B-1：lastEndedTurn 提交后置三态化（issue #290）——推进移到分流
          // 判定与入队之后：发出成功 / 免打扰拦截（suppressed） / 开关禁用
          // （notifyTaskDone=false / notifySubagentDone=false 未入队）三态均
          // 提交；批次成员按「入队成功」提交（doneBatcher.enqueue 被调用即推进，
          // 与 flushDoneMerge 成败解耦）；异常路径（外层 catch）不达此处不提交。
          if (best !== undefined) state.lastEndedTurn = best.turn;
        } else if (status === "running") {
          state.runningSeen = true;
          state.startedAt = Date.now();
          // 记录本轮开始前的快照基线（abort-early 冻结判据）：running 时
          // 快照最新 turn/end 即「本轮之前已落盘」的证据；idle 时快照若
          // 仍未推进（≤ 基线），说明本次 running→idle 无新 closure（abort
          // 早于 turn/start），陈旧快照不得当本轮新证据（C-1/D-2）。
          state.runningBaseline = lastTurnEndOf(agent);
        }
      } catch (error) {
        ctx.logger.warn(`dsh-notifier: agent/status 处理失败: ${errorMessage(error)}`);
      }
    }, { global: true })
  );

  /** 会话销毁时清理其状态机条目（含错误合并窗口、推送源记忆与 turn 去重，防 Map/Set 无界增长）。 */
  disposers.push(
    ctx.on("agent/disposed", ({ agent }) => {
      if (agent?.id !== undefined) {
        agentStates.delete(agent.id);
        eventStreamEnds.delete(agent.id);
        errorMerge.delete(agent.id);
        for (const key of [...turnNotified]) {
          if (key.startsWith(agent.id + ":")) turnNotified.delete(key);
        }
      }
    }, { global: true })
  );

  /** 合并错误表：per-agent 滚动窗口，窗口内后续错误不单独通知。 */
  const errorMerge = new Map<string, { count: number; since: number; lastMessages: string[] }>(); // agentId -> { count, since, lastMessages }

  /** 任务错误（60 秒滚动窗口内合并同类错误，防刷屏；窗口内被吞的错误保留
   *  最近 2 条摘要，窗口过期后随通知提示「窗口内其他错误」）。 */
  disposers.push(
    ctx.on("agent/error", (payload) => {
      try {
        if (!current.notifyTaskError) return;
        const agentId = payload?.agent?.id;
        const key = agentId ?? "?";
        const now = Date.now();
        const rawMessage = payload?.error instanceof Error ? payload.error.message : errorMessage(payload?.error);
        const sanitized = sanitizeErrorText(rawMessage);
        const mergeMs = current.errorMergeWindowMs;
        const prev = mergeMs > 0 ? errorMerge.get(key) : undefined;
        if (prev !== undefined && now - prev.since < mergeMs) {
          prev.count += 1;
          prev.since = now;
          prev.lastMessages.push(sanitized.slice(0, 80));
          if (prev.lastMessages.length > 2) prev.lastMessages.shift();
          // 合并分支落一条带标记的历史，确保用户可核对「到底发没发」
          appendHistory({ ts: now, kind: "error", title: "DSH：任务出错", message: `（合并）${sanitized.slice(0, 120)}`, suppressed: "merged" });
          return;
        }
        const mergedCount = prev !== undefined ? prev.count : 0;
        const mergedErrors = prev !== undefined ? prev.lastMessages : [];
        // 先通知，确认放行后再开窗/推进——免打扰拦截时不消耗合并窗口
        const notified = notify("error", {
          message: sanitized,
          taskTitle: sessionTitleOf(payload?.agent),
          turn: typeof payload?.turn === "number" ? payload.turn : undefined,
          step: typeof payload?.step === "number" ? payload.step : undefined,
          mergedCount,
          mergedErrors,
        });
        if (notified) {
          errorMerge.set(key, { count: 0, since: now, lastMessages: [] });
        }
      } catch (error) {
        ctx.logger.warn(`dsh-notifier: agent/error 处理失败: ${errorMessage(error)}`);
      }
    }, { global: true })
  );

  /** turn-stopping 已通知的 (agentId, turn) 去重（防同轮被反复 emit 时重复记录刷屏）。 */
  const turnNotified = new Set<string>();

  /** 轮结束（默认关）。cordis serial 事件签名是 cb(payload)，无 next——调用 next() 会 TypeError 且污染整轮。 */
  disposers.push(
    ctx.on("agent/turn-stopping", async (payload) => {
      try {
        if (current.notifyTurnEnd) {
          const turn = typeof payload?.turn === "number" ? payload.turn : NaN;
          const key = `${payload?.agent?.id ?? "?"}:${Number.isFinite(turn) ? turn : "?"}`;
          if (turnNotified.has(key)) return; // 同一 (agent, talk) 只通知一次，防刷屏
          turnNotified.add(key);
          notify("turn-end", {
            turn: Number.isFinite(turn) ? turn : undefined,
            taskTitle: sessionTitleOf(payload?.agent),
          });
        }
      } catch (error) {
        ctx.logger.warn(`dsh-notifier: turn-stopping 处理失败: ${errorMessage(error)}`);
      }
    }, { global: true })
  );

  // ------------------------------------------------------------ 路由注册

  // 关键：路由注册必须在 ctx.effect 内执行——apply 主体直接调用 ctx 服务
  // （webServer.register）会在 cordis isolate 链就绪前访问服务，触发
  // "Cyclic __proto__ value"（loader isolate 处理），导致插件激活失败。
  const routes = buildRoutes({
    // effective = settings 命名空间解析值（attach 后 current 已指向 scope.get()）
    resolve: () => current,
    readUser,
    writable: () => attachedService !== undefined,
    update: updateConfig,
    logger: ctx.logger,
    sse,
    system,
    history: historyStore,
    sendTest: (channelId?: string) => notifierService.sendKind("test", {}, { bypassQuiet: true, onlyChannel: channelId }),
    statusReader: () => statusStore.read(),
    listKinds: () => notifierService.listKinds(),
    setConfirm: confirmKindToConfig,
  });
  const disposeRoutes = ctx.effect(
    () => {
      const routeDisposers = routes.map((route) => ctx.webServer.register(route));
      return () => {
        for (const dispose of routeDisposers) {
          try {
            dispose();
          } catch {
            // 忽略
          }
        }
      };
    },
    "dsh-notifier: routes"
  );

  // ------------------------------------------------------------ settings 接线 + 存量迁移

  // GUI 设置卡片数据面 + 存量迁移（issue #76）：settings 命名空间 attach 后——
  //   1. onScope 内先做存量 dsh-notifier.json 迁移（前置于一切 enabled 判定，
  //      禁用用户升级/禁用态同样迁移，E7）；
  //   2. setSource 把读取来源切到 scope.get()（schema defaults → base(entry) →
  //      user 层的官方解析顺序，无双轨合并）；
  //   3. 热更新统一由 scope.watch 驱动 onChange 刷新 current 镜像。
  // 服务缺失（未注入 settings）时：writable=false → PUT 503，路由/通知保持降级
  // 可用（current 恒为组合层 entry 归一化值），与 lan-proxy 同语义。
  installNotifierSettings(ctx, entry, {
    setSource: (s) => {
      source = s;
      // 收口归一化（#436 复核 P1-1）：setSource 与 onChange 两处都过 normalizeConfig
      // ——服务消失回落时 s() 为裸 entry，需默认值兜底才能与初始 current
      // （normalizeConfig(entry)）形态一致；normalizeConfig 幂等，对 scope.get()
      // 的官方解析结果重复归一化无害。
      current = normalizeConfig(s());
    },
    onChange: () => {
      current = normalizeConfig(source());
    },
    onScope: (scope, service) => {
      attachedScope = scope;
      attachedService = service;
      // 迁移（rename-first 幂等；损坏/中断/回滚均在 migrate.ts 内处理并 warn，
      // 失败不阻塞启动——E6）。迁移完成判定 = 逐字段缺失补齐（#468：不再以
      // 「user 层已有任意值 = 迁移已完成」整体跳过——部分写入中断后剩余 legacy
      // 字段会永久漏迁）；readUser 供 diffMissingKeys 只补写 user 层缺失键。
      void migrateLegacyConfig(
        storeFile,
        {
          update: (patch) => service.update(SETTINGS_NS, patch),
          readUser: () => readUser().user,
        },
        ctx.logger
      ).catch((err) => {
        ctx.logger.warn(`dsh-notifier: 存量配置迁移异常 — ${errorMessage(err)}`);
      });
    },
  });

  // ------------------------------------------------------------ 启动与清理

  // 配置源已就绪（entry 归一化）；若 settings 已 attach（inject 回调同步触发），
  // current 已指向 scope.get()。无需 loadConfig（自建 json 读写链路已废弃）。

  // ⚠️ 清理必须放在 effect **返回的 disposer** 里，不能写在 fn 主体：
  // ctx.effect(fn) 的 fn 在 apply 时立即同步执行，只有返回值才在 fiber
  // 卸载时调用。若把 disposeRoutes() 写在 fn 主体，等于注册完立刻注销。
  ctx.effect(
    () => () => {
      sse.dispose();
      // M4 定时器清理：审批提醒、完成风暴窗口（聚合批处理器内部）
      for (const t of askRemindTimers.values()) clearTimeout(t);
      askRemindTimers.clear();
      doneBatcher.dispose();
      turnNotified.clear();
      for (const dispose of disposers) {
        try {
          dispose();
        } catch {
          // 忽略
        }
      }
      disposeRoutes();
    },
    "dsh-notifier"
  );
}

packages/dsh-notifier/src/server.ts.source:
/**
 * dsh-notifier — 服务器侧逻辑：SSE 推送、系统通知通道、HTTP 路由。
 *
 * 全部可变状态经工厂函数收口（createSseHub / createSystemNotifier），
 * 路由经 buildRoutes(deps) 纯组装——deps 由 index.ts 装配层注入，
 * 本模块自身不持有跨请求状态以外的生命周期职责。
 *
 * #515：SSE 连接管理（表/心跳/上限淘汰/stalled+maxAge 主动回收）收敛到
 * shared/sse-hub.js 单一实现（连接状态机）；本文件保留 notifier 业务包装
 * （seq + 滚动缓冲 + ?since 补拉）与对外接口不变。
 */
import { spawn, execFile } from "node:child_process";
import type { ChildProcess } from "node:child_process";
import type { ServerResponse } from "node:http";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { writeJson, readBody, errorMessage, sseData, guardLoopbackMethod } from "../../../shared/host-utils.js";
import { createSseHub as createSharedHub } from "../../../shared/sse-hub.js";
import type { NotifyConfig } from "./config.ts";
import { sanitizePatchSettings, validateSettings, redactConfigView, unmaskChannels } from "./config.ts";
import type { HistoryStore } from "./history.ts";
import { buildSystemCommand } from "./message.ts";

/** 与客户端共享的路由常量（smoke 断言两端一致）。 */
export const ROUTES = {
  config: "/api/dsh-notifier/config",
  events: "/api/dsh-notifier/events",
  health: "/api/dsh-notifier/health",
  test: "/api/dsh-notifier/test",
  history: "/api/dsh-notifier/history",
  status: "/api/dsh-notifier/status",
  kinds: "/api/dsh-notifier/kinds",
};

/** SSE 推送枢纽：连接表、滚动缓冲广播、心跳。
 *  #515：连接管理（表/心跳/上限淘汰/stalled+maxAge 回收）收敛到 shared/sse-hub.js，
 *  本接口保留 notifier 业务面（broadcast(payload) 带 seq+滚动缓冲、framesSince 补拉）。
 *  类型 = 共享 hub 核心面 + notifier 业务广播（对象负载）+ 滚动缓冲回放。
 */
import type { SseConnHealth, SseEvictStats } from "../../../shared/sse-hub.js";
export type { SseConnHealth, SseEvictStats };
export type { SseHubOptions } from "../../../shared/sse-hub.js";

/** notifier 视角的 SSE 枢纽：共享连接管理面 + 业务广播 + 断线补拉。
 *  注意不 extends 共享 SseHub：共享的 broadcast(text) 是「写现成帧」原语，
 *  本接口的 broadcast(payload) 是「对象负载 → 附加 seq → 广播」业务语义，
 *  两者签名不同，用组合而非继承（register/size/dispose 委托共享 hub）。 */
export interface SseHub {
  /** 注册一条 SSE 连接：入表 + 挂 close/error 监听 + 上限淘汰（委托共享 hub）。 */
  register(res: ServerResponse): void;
  /** 广播一帧业务通知：附加递增 seq、入滚动缓冲、推给所有连接。 */
  broadcast(payload: Record<string, unknown>): void;
  /** 断线补拉：滚动缓冲中 seq 更大的帧（独立于 /history 截断）。 */
  framesSince(since: number): Array<Record<string, unknown> & { seq: number }>;
  /** 当前连接数（语义 = 服务端未释放句柄数）。 */
  size(): number;
  /** evict 原因计数（health 观测）。 */
  evictStats(): SseEvictStats;
  /** 连接健康快照（health per-conn 观测）。 */
  connHealth(now?: number): SseConnHealth[];
  /** 停止心跳定时器。 */
  dispose(): void;
}

/**
 * 创建 SSE 枢纽（notifier 业务包装）。
 *
 * 连接管理（register/size/dispose/心跳/stalled+maxAge 回收）委托共享 hub
 * （shared/sse-hub.js，#515）；本包装在共享 hub 之上叠加 notifier 业务广播：
 * broadcast(payload) 附加递增 seq、入 600 条滚动缓冲（断线回放独立于 /history
 * 截断），framesSince(since) 供 events 路由 ?since 补拉。
 *
 * @param options.getMaxConnections 连接上限实时读取器（配置改动即时生效）。
 * @param options.heartbeatMs 心跳间隔（默认 30s；测试注入短值）。
 * @param options.stalledTimeoutMs stalled 回收窗口（默认 90s；测试注入短值）。
 * @param options.maxAgeMs maxAge 轮换上限（默认 120min；0 = 关闭轮换）。
 * @param options.idleTimeoutMs maxAge 轮换空闲门槛（默认 15min）。
 */
export function createSseHub(options: {
  getMaxConnections: () => number;
  heartbeatMs?: number;
  stalledTimeoutMs?: number;
  maxAgeMs?: number;
  idleTimeoutMs?: number;
}): SseHub {
  const { getMaxConnections } = options;
  // 共享 hub：连接表 + 心跳 + 上限淘汰 + stalled/maxAge 主动回收（单一实现）。
  const hub = createSharedHub({
    getMaxConnections,
    heartbeatMs: options.heartbeatMs,
    stalledTimeoutMs: options.stalledTimeoutMs,
    maxAgeMs: options.maxAgeMs,
    idleTimeoutMs: options.idleTimeoutMs,
  });

  /** SSE 已派发帧的滚动缓冲（断线回补用；上限 RECENT_LIMIT，独立于 /history 的
   *  200 条截断，避免补拉时尾部事件被截掉）。 */
  const RECENT_LIMIT = 600;
  let notifySeq = 0;
  const recentFrames: Array<Record<string, unknown> & { seq: number }> = [];

  return {
    register: hub.register,
    size: hub.size,
    dispose: hub.dispose,
    evictStats: hub.evictStats,
    connHealth: hub.connHealth,
    /** 业务广播：附加 seq → 入滚动缓冲 → 经共享 hub 写全部连接（判死收口在 hub）。 */
    broadcast(payload: Record<string, unknown>) {
      const frame: Record<string, unknown> & { seq: number } = Object.assign({}, payload, { seq: ++notifySeq });
      recentFrames.push(frame);
      if (recentFrames.length > RECENT_LIMIT) recentFrames.shift();
      hub.broadcast(sseData(frame));
    },
    /** 断线补拉：滚动缓冲中 seq 更大的帧（?since 语义不变）。 */
    framesSince(since: number) {
      return recentFrames.filter((frame) => frame.seq > since);
    },
  };
}

/** 系统通知通道：节流 + 子进程生命周期兜底。 */
export interface SystemNotifier {
  /** 发一条系统原生 toast（fire-and-forget；全部失败静默）。 */
  notify(title: string, message: string): void;
}

/**
 * 创建系统通知通道。
 * @param options.getSoundEnabled 提示音开关的实时读取器（PUT /config 后立即生效）。
 * @param options.toastScript toast.ps1 路径。
 * @param options.warn 日志出口（ctx.logger.warn）。
 */
export function createSystemNotifier(options: { getSoundEnabled: () => boolean; toastScript: string; warn: (message: string) => void }): SystemNotifier {
  const { getSoundEnabled, toastScript, warn } = options;

  /** 系统通知节流间隔：防连发（生产密集事件/连点测试按钮）造成 spawn 风暴。 */
  const SYSTEM_NOTIFY_THROTTLE_MS = 1000;
  let lastSystemNotifyAt = 0;

  /** notify-send 可用性探测（仅 Linux 需要；macOS 走 osascript，darwin 分支
   *  不依赖此探测，故不在 macOS 上无谓尝试缺失的 notify-send）。异步，只探一次。 */
  let notifySendAvailable: boolean | undefined = undefined;
  if (process.platform === "linux") {
    execFile("notify-send", ["--version"], { timeout: 3000 }, (error) => {
      notifySendAvailable = error === null;
    });
  }

  return {
    /**
     * 系统原生 toast（fire-and-forget + 30s 超时杀进程；全部失败静默）。
     * 命令构造走 message.ts 纯函数 buildSystemCommand（smoke 断言参数形态）：
     * Windows：PowerShell WinRT toast；macOS：osascript display notification；
     * 其他：notify-send（可用才调用）。
     */
    notify(title: string, message: string) {
      // 1s 节流：桌面通知连发只保留第一个，避免子进程风暴
      const now = Date.now();
      if (now - lastSystemNotifyAt < SYSTEM_NOTIFY_THROTTLE_MS) return;
      lastSystemNotifyAt = now;
      // 截断按码点而非 UTF-16 code unit：防 emoji 等代理对在边界被腰斩成
      // 孤立代理（经 JSON/base64 后变成 U+FFFD 替换符显示，issue #238 配套）。
      const truncateCodePoints = (s: string, max: number): string => {
        const chars = Array.from(s);
        return chars.length > max ? chars.slice(0, max).join("") : s;
      };
      const safeTitle = truncateCodePoints(String(title), 64);
      const safeMessage = truncateCodePoints(String(message), 256);
      let child: ChildProcess | undefined;
      let bin = "";
      try {
        const argv = buildSystemCommand(process.platform, safeTitle, safeMessage, {
          silent: getSoundEnabled() === false,
          notifySendAvailable,
          toastScript,
        });
        if (argv === null) return; // 通道不可用（如 Linux 探测到 notify-send 缺失）：静默跳过
        bin = argv[0];
        // 关键：原生二进制缺失/不可执行（ENOENT 等）必须被下方 error 事件接住，
        // 绝不能冒泡成 unhandled 'error' 把宿主进程打挂——历史版本在 macOS 上因
        // 直接 spawn powershell 失败且未挂 error 监听而崩溃（见 issue #1）。
        child = spawn(bin, argv.slice(1), process.platform === "win32" ? { windowsHide: true, stdio: ["ignore", "ignore", "pipe"] } : { stdio: "ignore" });
      } catch (error) {
        warn(`dsh-notifier: 系统通知启动失败: ${errorMessage(error)}`);
        return;
      }
      if (!child) return; // 极端情况下 spawn 返回空（理论上不会），直接放弃，不碰 child
      // Windows 分支限长收集 stderr：PS 的诊断（param 绑定失败、WinRT 异常等）
      // 原先随 stdio ignore 全部丢弃，排查只能盲猜（issue #238）；只留尾部片段进日志。
      let stderrTail = "";
      if (process.platform === "win32" && child.stderr) {
        child.stderr.on("data", (chunk: Buffer) => {
          if (stderrTail.length < 512) stderrTail += chunk.toString("utf8");
        });
      }
      const killer = setTimeout(() => {
        try {
          child!.kill();
        } catch {
          // 忽略
        }
      }, 30000);
      // 任何退出码都先清杀手定时器；非 0 且非被信号杀死（null）才记日志，
      // 避免把「我们主动 30s 超时杀掉子进程」也当成异常刷屏。
      child.on("exit", (code) => {
        clearTimeout(killer);
        if (code !== 0 && code !== null) {
          const tail = stderrTail.trim();
          warn(`dsh-notifier: 系统通知退出码异常（exit ${code}）${tail ? `：${tail.slice(-300)}` : ""}`);
        }
      });
      // 通道失败（二进制不在 PATH / 无桌面会话等）：非 Windows 记一次后置为不可用，
      // 后续通知走 null 分支静默跳过；Windows 不置位（powershell 偶发失败不代表
      // WinRT toast 通道整体失效）。无论如何只记日志、不抛、不崩。
      child.on("error", (error) => {
        clearTimeout(killer);
        if (process.platform !== "win32") notifySendAvailable = false;
        warn(`dsh-notifier: 系统通知不可用（${bin}）: ${errorMessage(error)}`);
      });
    },
  };
}

/** buildRoutes 的依赖注入面（全部由 index.ts 装配层提供）。 */
export interface RouteDeps {
  /** 当前生效配置（schemastery 解析值，含默认值兜底；GET /config 的 effective）。 */
  resolve(): NotifyConfig;
  /** settings user 层原始节与 revision（describe({redactSecrets:true}) 读取）。 */
  readUser(): { user: Record<string, unknown>; revision?: number };
  /** settings 服务是否可用（决定 PUT 是否可写：writable:false → 503）。 */
  writable(): boolean;
  /** 增量 merge patch 进 settings user 层（乐观并发经 expectedRevision）。 */
  update(patch: object, expectedRevision?: number): Promise<void>;
  /** 日志出口。 */
  logger: { warn: (message: string) => void; info: (message: string) => void };
  /** SSE 推送枢纽。 */
  sse: SseHub;
  /** 系统通知通道。 */
  system: SystemNotifier;
  /** 通知历史存储。 */
  history: HistoryStore;
  /** 测试通知（收敛到 service 管线；channelId 可选指定单频道——per-channel 测试）。 */
  sendTest(channelId?: string): Array<{ channelId: string; status: string; error?: string }>;
  /** 频道投递状态读取（GET /status；per-channel 最近投递终态）。 */
  statusReader(): Promise<Record<string, unknown>>;
  /** 动态 kind 清单（GET /kinds；含确认态）。 */
  listKinds(): Array<{ id: string; label: string; confirmed: boolean }>;
  /** 动态 kind 确认写入（POST /kinds；持久化到配置 allowKinds）。 */
  setConfirm(kind: string, confirmed: boolean): Promise<void>;
}

/** applyConfigPatch 的结果。 */
export type PatchResult =
  | { ok: true; value: { user: Record<string, unknown>; revision?: number } }
  | { ok: false; status: number; code: string; response: Record<string, unknown> };

/**
 * 配置保存纯函数（PUT /config 的主体，独立导出供 smoke 单测）：
 * channels[].deviceKey 掩码按 id 对齐回填 user 层原值（评审 P0-2：必须先于
 * 校验，掩码不是合法 key 语义）→ validateSettings 定位首个非法键（400 + hint）
 * → sanitizePatchSettings 净化（已知键校验 + 未知键透传保留、装配键剔除，
 * #470）→ 经 settings 服务 update 增量写入（expectedRevision
 * 可选做乐观并发）。错误映射（R3）：SETTINGS_CONFLICT → 409 固定文案；settings
 * 缺失 → 503 settings-unavailable；写入异常原文只进服务端日志（P2-2）。
 * 成功响应的 user 经 redactConfigView 统一脱敏（评审 P0-1 单一出口）。
 */
export async function applyConfigPatch(deps: RouteDeps, payload: unknown): Promise<PatchResult> {
  if (!deps.writable()) {
    return { ok: false, status: 503, code: "settings-unavailable", response: { error: "设置服务不可用", code: "settings-unavailable" } };
  }
  const body = (typeof payload === "object" && payload !== null ? payload : {}) as {
    patch?: unknown;
    expectedRevision?: unknown;
  };
  const expectedRevision =
    typeof body.expectedRevision === "number" && Number.isInteger(body.expectedRevision) ? body.expectedRevision : undefined;
  const rawPatch = body.patch;
  // 掩码回填先于校验（评审 P0-2）：channels 实例的 deviceKey 整值等于掩码时按
  // id 对齐回填 user 层原值；新实例（user 层无同 id）带掩码 → 400 拒绝。
  let effectivePatch: unknown = rawPatch;
  if (typeof rawPatch === "object" && rawPatch !== null && Array.isArray((rawPatch as Record<string, unknown>).channels)) {
    const userChannels = (deps.readUser().user as Record<string, unknown> | undefined)?.channels;
    const unmasked = unmaskChannels((rawPatch as Record<string, unknown>).channels, userChannels);
    if (!unmasked.ok) {
      return {
        ok: false,
        status: 400,
        code: "invalid",
        response: { error: "配置校验失败: channels", hint: "新增实例的 deviceKey 不能为掩码占位（********），请填入真实 key" },
      };
    }
    effectivePatch = { ...(rawPatch as Record<string, unknown>), channels: unmasked.channels };
  }
  // 先定位首个非法键（H6）：错误文案指明字段与合法范围，不再静默丢弃回默认
  const invalid = validateSettings(effectivePatch);
  if (invalid !== null) {
    return { ok: false, status: 400, code: "invalid", response: { error: `配置校验失败: ${invalid.key}`, hint: invalid.hint } };
  }
  // #470 双通道拆分后 PUT 走透传净化（未知键保留、装配键剔除）：
  // 「至少一个有效配置键」判据改为「原始 patch 非空对象」——纯未知键 patch
  // （如 {futureKey:1}）→ 200 透传写入；仅空 patch {}（无任何键可写）→ 400。
  if (typeof rawPatch !== "object" || rawPatch === null || Object.keys(rawPatch).length === 0) {
    return { ok: false, status: 400, code: "invalid", response: { error: "配置校验失败: patch", hint: "需至少包含一个配置键（patch 不能为空）" } };
  }
  const sanitized = sanitizePatchSettings(effectivePatch);
  if (sanitized === null || Object.keys(sanitized).length === 0) {
    // null = 已知键非法（validateSettings 已拦，理论不可达兜底）；空对象 =
    // 原始 patch 仅含装配键（剔除后无任何可写键）→ 同空 patch 语义 400
    return { ok: false, status: 400, code: "invalid", response: { error: "配置校验失败: patch", hint: "需至少包含一个有效配置键" } };
  }
  try {
    await deps.update(sanitized as Record<string, unknown>, expectedRevision);
  } catch (err) {
    const code = (err as { code?: unknown })?.code;
    if (code === "SETTINGS_CONFLICT") {
      return { ok: false, status: 409, code: "conflict", response: { error: "版本冲突", code: "SETTINGS_CONFLICT" } };
    }
    // P2-2：对外收敛固定文案，不把底层异常原文（可能含路径等内部信息）回给
    // 客户端；完整原因走服务端日志。
    deps.logger.warn(`dsh-notifier: 配置保存写入设置存储失败 — ${errorMessage(err)}`);
    return { ok: false, status: 500, code: "error", response: { error: "保存失败，请查看服务端日志" } };
  }
  // 单一脱敏出口（评审 P0-1）：readUser 的 user 含 channels 明文，掩码后返回
  const fresh = deps.readUser();
  return { ok: true, value: { user: redactConfigView(fresh.user), revision: fresh.revision } };
}

/**
 * 构造五条路由（loopback 围栏 + 方法白名单是每条路由的必项）。
 * @returns WebRoute 数组（调用方逐条 register，收集 disposer）。
 */
export function buildRoutes(deps: RouteDeps): WebRoute[] {
  const { resolve, readUser, writable, update, logger, sse, history, sendTest, statusReader, listKinds, setConfirm } = deps;

  const configRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.config,
    handler: async (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET", "PUT"])) return;
      if (req.method === "GET") {
        const { user, revision } = readUser();
        // 凭据脱敏单一出口（评审 P0-1）：user 与 effective 双视图都经
        // redactConfigView 掩码 deviceKey——深度扫描契约测试锁死两出口。
        writeJson(res, 200, {
          ok: true,
          user: redactConfigView(user),
          revision,
          effective: redactConfigView(resolve()),
          writable: writable(),
        });
        return;
      }
      if (req.method === "PUT") {
        let body: unknown;
        try {
          body = await readBody(req, 16 * 1024);
        } catch (error) {
          const message = errorMessage(error);
          if (message.includes("invalid JSON body")) {
            // 非法 JSON：连接尚存，返回可读 400，避免请求「无响应挂起」
            writeJson(res, 400, { ok: false, error: { code: "invalid-json", details: `invalid JSON body: ${message}` } });
            return;
          }
          // 超限路径：readBody 已 reject 并 destroy 连接（防超大 body 占内存），
          // socket 已断开无法再写响应——记录日志即可（shared/host-utils.js 语义）
          logger.warn(`dsh-notifier: 配置请求体读取失败: ${message}`);
          return;
        }
        // #470 复核 P0-2 兜底：applyConfigPatch 内部异常（理论不可达——净化/
        // 校验/脱敏对任意输入均收敛为错误分支，此处防未来改动引入未捕获抛错）
        // 不得让 handler 冒泡成宿主 500/悬挂——收敛 500 固定文案 + 服务端日志
        let result: PatchResult;
        try {
          result = await applyConfigPatch(deps, body);
        } catch (error) {
          logger.warn(`dsh-notifier: 配置保存处理异常 — ${errorMessage(error)}`);
          writeJson(res, 500, { ok: false, error: { error: "保存失败，请查看服务端日志" } });
          return;
        }
        if (!result.ok) {
          writeJson(res, result.status, { ok: false, error: result.response });
          return;
        }
        writeJson(res, 200, { ok: true, user: result.value.user, revision: result.value.revision });
        return;
      }
      writeJson(res, 405, { error: `method not allowed: ${req.method}` });
    },
  };

  const eventsRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.events,
    handler: (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET"])) return;
      if (req.method !== "GET") {
        writeJson(res, 405, { error: `method not allowed: ${req.method}` });
        return;
      }
      // ?since=<seq>：断线补拉——先回放滚动缓冲中 seq 更大的帧，再进入实时；
      // 补拉独立于 /history（200 条截断），不丢尾部事件。
      let since = 0;
      try {
        const raw = new URL(req.url ?? "/", "http://127.0.0.1").searchParams.get("since");
        const parsed = raw === null ? 0 : Number(raw);
        since = Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : 0;
      } catch {
        since = 0;
      }
      res.writeHead(200, {
        "content-type": "text/event-stream",
        "cache-control": "no-cache",
        connection: "keep-alive",
      });
      // 预存在缺口随手修（#334 评审遗留 P2-9）：connected 锚点写失败（对端已断）
      // 直接返回、不再 register——已断连接入表只会成为靠心跳/广播兜底清理的残留。
      try {
        res.write(": connected\n\n");
      } catch {
        return;
      }
      if (since > 0) {
        for (const frame of sse.framesSince(since)) {
          try {
            res.write(sseData(frame));
          } catch {
            break; // 连接已断
          }
        }
      }
      // 入表 + 挂 close/error 监听 + 连接上限淘汰，全部收口在 sse.register
      sse.register(res);
    },
  };

  /** 健康检查：插件是否加载、配置摘要、SSE 连接数与回收观测。
   *  sseConnections 语义 = 服务端未释放的 SSE 句柄数，非「在线设备数」；上限见
   *  config.maxConnections。#515 起连接表由 shared/sse-hub 管理：stalled 超窗 /
   *  maxAge 轮换主动回收 + 上限淘汰，sseEvicts 暴露各回收路径计数（观测残留构成），
   *  sseConnHealth 暴露逐连接 age/lastWriteAgo/stalled（先量化再调参）。 */
  const healthRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.health,
    handler: (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET"])) return;
      if (req.method !== "GET") return writeJson(res, 405, { error: `method not allowed: ${req.method}` });
      const current = resolve();
      writeJson(res, 200, {
        ok: true,
        plugin: "dsh-notifier",
        config: {
          notifyAsk: current.notifyAsk,
          notifyQuestion: current.notifyQuestion,
          notifyTaskDone: current.notifyTaskDone,
          notifySubagentDone: current.notifySubagentDone,
          notifyTaskError: current.notifyTaskError,
          systemNotify: current.systemNotify,
          browserNotify: current.browserNotify,
          notifyWhenVisible: current.notifyWhenVisible,
          notifySound: current.notifySound,
          quietHours: current.quietHours,
          maxConnections: current.maxConnections,
        },
        sseConnections: sse.size(),
        sseEvicts: sse.evictStats(),
        sseConnHealth: sse.connHealth(),
      });
    },
  };

  /**
   * 测试通知：POST 触发一条测试通知（绕过免打扰，测试意图是验证通道本身）。
   * M2 收敛到 service 管线（sendKind('test')）：内置 browser/system 与配置驱动
   * 频道（bark）走同一分发路径——测试才有意义（验证真实投递链路），历史落盘
   * 与终态上报（status/sent 事件）同源。body 可选 {channelId}：指定单频道测试
   * （设置页频道卡「测试」按钮）。固定文案模板，不引入自由文本面（评审定案）。
   * 返回的 sseConnections 语义同 /health = 服务端未释放句柄数（非设备数）。
   */
  const testRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.test,
    handler: async (req, res) => {
      if (!guardLoopbackMethod(req, res, ["POST"])) return;
      if (req.method !== "POST") return writeJson(res, 405, { error: `method not allowed: ${req.method}` });
      let channelId: string | undefined;
      try {
        // body 可选：无 body / 测试桩无流 → channelId 保持 undefined（全频道测试）
        const parsed = (await readBody(req, 4 * 1024)) as { channelId?: unknown } | null;
        if (parsed && typeof parsed === "object" && typeof parsed.channelId === "string" && parsed.channelId.length > 0) {
          channelId = parsed.channelId;
        }
      } catch (error) {
        const message = errorMessage(error);
        if (message.includes("invalid JSON body")) {
          writeJson(res, 400, { ok: false, error: { code: "invalid-json", details: `invalid JSON body: ${message}` } });
          return;
        }
        // 其余（无 body 流的桩请求 / 超限 destroy）：body 可选语义，按全频道测试继续
        logger.warn(`dsh-notifier: 测试通知请求体读取失败（按无 body 处理）: ${message}`);
      }
      const results = sendTest(channelId);
      writeJson(res, 200, { ok: true, sseConnections: sse.size(), results });
    },
  };

  /**
   * 频道投递状态：GET 返回 per-channel 最近投递终态（status 文件内存镜像）。
   * 设置页频道卡状态区消费（ok 灰 / failed 高亮 + 错误摘要——已脱敏）。
   */
  const statusRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.status,
    handler: async (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET"])) return;
      if (req.method !== "GET") return writeJson(res, 405, { error: `method not allowed: ${req.method}` });
      const channels = await statusReader();
      writeJson(res, 200, { ok: true, channels });
    },
  };

  /**
   * 动态 kind 清单与确认：GET 返回注册表（含确认态，确认态持久化在配置
   * allowKinds）；POST {kind, confirmed} 写确认（仅注册表内已注册的动态 kind）。
   * 确认动作只发生在用户主动打开设置页时（终稿 §5.1：注册即弹窗打扰不允许）。
   */
  const kindsRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.kinds,
    handler: async (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET", "POST"])) return;
      if (req.method === "GET") {
        writeJson(res, 200, { ok: true, kinds: listKinds() });
        return;
      }
      if (req.method === "POST") {
        let body: unknown;
        try {
          body = await readBody(req, 4 * 1024);
        } catch (error) {
          const message = errorMessage(error);
          if (message.includes("invalid JSON body")) {
            writeJson(res, 400, { ok: false, error: { code: "invalid-json", details: `invalid JSON body: ${message}` } });
            return;
          }
          logger.warn(`dsh-notifier: kind 确认请求体读取失败: ${message}`);
          return;
        }
        const { kind, confirmed } = (typeof body === "object" && body !== null ? body : {}) as { kind?: unknown; confirmed?: unknown };
        if (typeof kind !== "string" || kind.length === 0 || typeof confirmed !== "boolean") {
          writeJson(res, 400, { ok: false, error: { code: "invalid", details: "需为 { kind: string, confirmed: boolean }" } });
          return;
        }
        const known = listKinds().some((k) => k.id === kind);
        if (!known) {
          writeJson(res, 404, { ok: false, error: { code: "not-found", details: `未注册的动态 kind: ${kind}` } });
          return;
        }
        // #405 PR3：setConfirm 现为 CAS 循环（可抛 SETTINGS_CONFLICT 耗尽 / 服务
        // 缺失 rejection）——handler 必须兜底（评审 P1-1），防 rejection 冒泡成
        // 宿主行为未定义；200 响应体带新 revision（向后兼容新增字段）供客户端
        // confirmOne 同步 meta——修「确认 kind 后同窗口保存必 409」的版本链断点。
        try {
          await setConfirm(kind, confirmed);
        } catch (error) {
          const code = (error as { code?: unknown })?.code;
          if (code === "SETTINGS_CONFLICT") {
            writeJson(res, 409, { ok: false, error: { code: "SETTINGS_CONFLICT", error: "版本冲突" } });
            return;
          }
          if (code === "SETTINGS_UNAVAILABLE") {
            // 与 PUT /config 的服务缺失语义一致（#405 PR3 复核）：settings 服务未
            // attach → 503，而非笼统 500——保持跨通道错误映射一致。
            writeJson(res, 503, { ok: false, error: { code: "settings-unavailable", error: "设置服务不可用" } });
            return;
          }
          logger.warn(`dsh-notifier: kind 确认写入失败 — ${errorMessage(error)}`);
          writeJson(res, 500, { ok: false, error: { error: "确认失败，请查看服务端日志" } });
          return;
        }
        const { revision: freshRevision } = readUser();
        writeJson(res, 200, { ok: true, kinds: listKinds(), revision: freshRevision });
        return;
      }
      writeJson(res, 405, { error: `method not allowed: ${req.method}` });
    },
  };

  /** 通知历史：GET 返回最近记录（jsonl 尾部最多 HISTORY_LIMIT 条）。 */
  const historyRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.history,
    handler: async (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET", "DELETE"])) return;
      if (req.method === "GET") {
        const records = await history.read();
        writeJson(res, 200, { ok: true, records });
        return;
      }
      if (req.method === "DELETE") {
        const removed = await history.clear();
        writeJson(res, 200, { ok: true, removed });
        return;
      }
      writeJson(res, 405, { error: `method not allowed: ${req.method}` });
    },
  };

  return [configRoute, eventsRoute, healthRoute, testRoute, historyRoute, statusRoute, kindsRoute];
}

