    const ctx1 = makeFakeCtx({});
    ctx1.ctx.provide("settings", shared.service);
    apply(ctx1.ctx, { enabled: true, configFile: legacy, historyFile: join(work, "e2-hist.jsonl") });
    await pollUntil(() => shared.getUser().notifyAsk === false);
