      assert.deepEqual(out, { performed: false, migrated: false, rolledBack: false, skippedCorrupt: true, skippedIdempotent: false, resumed: true }, "E8：中断态 bak 损坏 → 标记跳过");
      assert.equal(d.updates.length, 0, "E8：损坏 bak 不写入");
    }
