        const allowedBase = baseInst.settings.getUser().allowKinds || [];
        assert.ok(allowedBase.includes("e2e:base1"), "确认的新 kind 已写入 user 层");
        assert.ok(allowedBase.includes("base:k0"), "#405：base 层豁免项未被空集覆盖（user 未接管时回退解析值合并）");
      } finally {
